=== rxclaim-emulator application.yml ===
server:
  port: 8091   # internal-only legacy core; fronted by claims-service, never the edge gateway

spring:
  application:
    name: rxclaim-emulator
  datasource:
    # H2 in-memory stands in for Db2 for i. In cloud this maps to Cloud SQL / Postgres.
    url: jdbc:h2:mem:rxclaim;DB_CLOSE_DELAY=-1
    driver-class-name: org.h2.Driver
    username: sa
    password: ""
  sql:
    init:
      mode: always   # run schema.sql + data.sql on startup

management:
  endpoints:
    web:
      exposure:
        include: health,info
  endpoint:
    health:
      probes:
        enabled: true   # liveness/readiness for Cloud Run / k8s

=== rxclaim-emulator Dockerfile ===
# Multi-stage build for the rxclaim-emulator (internal-only legacy core).
FROM maven:3.9-eclipse-temurin-21 AS build
WORKDIR /app
COPY pom.xml .
RUN mvn -q -B dependency:go-offline
COPY src ./src
RUN mvn -q -B -DskipTests package

FROM eclipse-temurin:21-jre
WORKDIR /app
COPY --from=build /app/target/rxclaim-emulator-*.jar app.jar
EXPOSE 8091
# NOTE: internal-only service. In cloud it runs with Cloud Run ingress=internal (see infra/).
ENTRYPOINT ["java", "-jar", "/app/app.jar"]

=== rxclaim-emulator Application class ===
package com.payer.rxclaim;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;

/**
 * Simulated legacy IBM i / RxClaim adjudication core (Phase 2, M2).
 *
 * <p>This service stands in for the legacy RxClaim engine that historically runs on IBM i
 * (Db2 for i, RPG/CL). In the modernization "strangler snapshot" it still owns the member
 * system-of-record, drug pricing, and accumulators; the modern claims-service wraps it behind
 * a fa&ccedil;ade + anti-corruption layer and never lets consumers call it directly.
 *
 * <p>It speaks a deliberately legacy contract: fixed-width (DDS-style) request/response
 * records over a REST fa&ccedil;ade, backed by DB2/SQL400-style tables. It is internal-only
 * (no edge gateway route; Cloud Run {@code ingress=internal} in cloud).
 */
@SpringBootApplication
public class RxClaimEmulatorApplication {
    public static void main(String[] args) {
        SpringApplication.run(RxClaimEmulatorApplication.class, args);
    }
}

=== AdjudicationController ===
package com.payer.rxclaim.api;

import com.payer.rxclaim.core.RxClaimCore;
import com.payer.rxclaim.legacy.LegacyClaimRecord;
import com.payer.rxclaim.legacy.LegacyResponseRecord;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

/**
 * REST fa&ccedil;ade over the legacy core. Intentionally speaks the legacy contract:
 * a fixed-width claim record in ({@code text/plain}), a fixed-width response record out.
 *
 * <p>The modern claims-service (M3) owns the anti-corruption layer that builds this record
 * from a canonical claim and parses the response back into FHIR — consumers never call this
 * service directly. It is internal-only (Cloud Run {@code ingress=internal}); no edge route.
 */
@RestController
@RequestMapping("/rxclaim")
public class AdjudicationController {

    private final RxClaimCore core;

    public AdjudicationController(RxClaimCore core) {
        this.core = core;
    }

    @PostMapping(value = "/adjudicate",
            consumes = MediaType.TEXT_PLAIN_VALUE,
            produces = MediaType.TEXT_PLAIN_VALUE)
    public ResponseEntity<String> adjudicate(@RequestBody String claimRecord) {
        String rec = claimRecord == null ? "" : claimRecord.replaceAll("\\R+$", "");
        LegacyClaimRecord claim;
        try {
            claim = LegacyClaimRecord.parse(rec);
        } catch (RuntimeException e) {
            // Malformed legacy record — this is a transport/format error, not an adjudication.
            return ResponseEntity.badRequest().body("ERR " + e.getMessage());
        }
        LegacyResponseRecord response = core.adjRxClm(claim);
        return ResponseEntity.ok(response.format());
    }
}

