8	import com.sun.net.httpserver.HttpServer;
9	import java.io.IOException;
10	import java.net.InetSocketAddress;
11	import java.nio.charset.StandardCharsets;
12	import java.time.LocalDate;
13	import java.util.concurrent.atomic.AtomicInteger;
14	import java.util.concurrent.atomic.AtomicReference;
15	import org.junit.jupiter.api.AfterEach;
16	import org.junit.jupiter.api.Test;
17	
18	/**
19	 * Contract test for the reused triage service, over a real HTTP round-trip against a stub server.
20	 *
21	 * <p>Two things are pinned here. First, the request really does carry {@code patient_id} — a
22	 * mocked client cannot catch a transport that silently sends an empty body, which is exactly how
23	 * the safety check once failed. Second, every path that does not yield a risk level we understand
24	 * maps to {@link RiskLevel#UNKNOWN}, never {@link RiskLevel#LOW}: "we could not check" must not be
25	 * indistinguishable from "we checked and it is safe", or claims approve on a check that never ran.
26	 */
27	class HttpTriageClientTest {
28	
29	    private HttpServer server;
30	    private final AtomicReference<String> lastBody = new AtomicReference<>();
31	    private final AtomicInteger calls = new AtomicInteger();
32	
33	    /** Starts a stub triage on a free port; returns its base URL. */
34	    private String startStub(int status, String responseBody) throws IOException {
35	        server = HttpServer.create(new InetSocketAddress("127.0.0.1", 0), 0);
36	        server.createContext("/triage/refill-risk", ex -> {
37	            calls.incrementAndGet();
38	            lastBody.set(new String(ex.getRequestBody().readAllBytes(), StandardCharsets.UTF_8));
39	            byte[] out = responseBody.getBytes(StandardCharsets.UTF_8);
40	            ex.getResponseHeaders().add("Content-Type", "application/json");
41	            ex.sendResponseHeaders(status, out.length);
42	            ex.getResponseBody().write(out);
43	            ex.close();
44	        });
45	        server.start();
46	        return "http://127.0.0.1:" + server.getAddress().getPort();
47	    }
48	
49	    @AfterEach
50	    void stopStub() {
51	        if (server != null) {
52	            server.stop(0);
53	        }
54	    }
55	
56	    private static String riskJson(String code) {
57	        return """
58	                {"resourceType":"RiskAssessment",
59	                 "prediction":[{"qualitativeRisk":{"coding":[{"code":"%s"}]}}]}""".formatted(code);
60	    }
61	
62	    private static CanonicalClaim claim() {
63	        return new CanonicalClaim("C1", "000000009", "COM-SILVER", "723", "0093-8675",
64	                "amoxicillin", 30, 30, LocalDate.of(2026, 6, 1), "1234567890",
65	                LocalDate.of(2026, 1, 1), LocalDate.of(2026, 12, 31), false, false);
66	    }
67	
68	    @Test
69	    void sendsPatientIdInTheRequestBody_andMapsHighRisk() throws IOException {
70	        String url = startStub(200, riskJson("high"));
71	
72	        RiskLevel risk = new HttpTriageClient(url).assess(claim(), "member-000000009");
73	
74	        assertThat(risk).isEqualTo(RiskLevel.HIGH);
75	        // The body must actually arrive — an empty body is the failure this test exists to catch.
76	        assertThat(lastBody.get()).contains("\"patient_id\"").contains("member-000000009");
77	    }
78	
79	    @Test
80	    void mapsLowRisk_whenTriageChecksAndFindsNothing() throws IOException {
81	        String url = startStub(200, riskJson("low"));
82	        assertThat(new HttpTriageClient(url).assess(claim(), "member-000000001"))
83	                .isEqualTo(RiskLevel.LOW);
84	    }
85	
