94	    void unresolvedMember_isUnknown_andTriageIsNotCalled() throws IOException {
95	        String url = startStub(200, riskJson("low"));
96	
97	        assertThat(new HttpTriageClient(url).assess(claim(), null)).isEqualTo(RiskLevel.UNKNOWN);
98	
99	        assertThat(calls.get()).isZero(); // no patient to ask about — do not guess, do not approve
